// STRICTLY READ ONLY queries of live Production D1; user requested discrepancy investigation.
// No schema changes, metadata writes or production Worker deploy. No customer personal information.
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
const prodId='17e68a41-1d58-4a36-8a63-47c3e32443c4'
const mirrorId='0904a573-21ff-44d8-93b0-c9200f771702'
const config=readFileSync('wrangler.jsonc','utf8')
assert(config.includes('"name": "orders-app-branch2"')&&config.includes(mirrorId)&&!config.includes(prodId),'Audit must run on isolated branch, not main')
const account=process.env.CLOUDFLARE_ACCOUNT_ID,token=process.env.CLOUDFLARE_API_TOKEN
assert(account&&token,'Cloudflare credentials missing')
const base='https://api.cloudflare.com/client/v4/accounts/'+account+'/d1/database/'+prodId
const headers={Authorization:'Bearer '+token,'Content-Type':'application/json'}
const info=await fetch(base,{headers,signal:AbortSignal.timeout(20000)})
assert(info.ok,'Production D1 metadata unavailable')
assert.equal((await info.json()).result?.name,'orders_db_prod')
const queries=[{"name":"PROD_RETURN_RESERVATION_CONFLICTS","sql":"SELECT o.id AS order_id,o.external_id,o.shipping_status,ret.id AS return_id,ri.order_item_id,oi.product_name_snapshot,oi.stock_writeoff_status,ri.quantity AS returned_qty,ri.physical_tracking,ri.physical_received_at,ri.inventory_source,ir.status AS reservation_status,ir.quantity AS reservation_qty,ir.inventory_source AS reservation_source,ir.variant_id FROM return_items ri JOIN returns ret ON ret.id=ri.return_id JOIN orders o ON o.id=ret.order_id JOIN order_items oi ON oi.id=ri.order_item_id JOIN inventory_reservations ir ON ir.order_item_id=ri.order_item_id WHERE COALESCE(ret.status,'completed') <> 'cancelled' AND ri.quantity>0 AND ir.status IN ('active','unresolved') AND NOT EXISTS(SELECT 1 FROM exchanges ex WHERE ex.refund_return_id=ret.id AND COALESCE(ex.status,'completed') <> 'cancelled') ORDER BY o.id,ret.id,ri.id LIMIT 70"},{"name":"PROD_OCTOBER_REFUNDS","sql":"WITH goods AS (SELECT return_id,SUM(quantity) AS goods_qty FROM return_items GROUP BY return_id) SELECT o.shipping_status,COUNT(*) AS returns_count,SUM(CASE WHEN r.amount>0 AND COALESCE(g.goods_qty,0)=0 THEN 1 ELSE 0 END) AS money_only,SUM(CASE WHEN r.amount>0 AND COALESCE(g.goods_qty,0)>0 THEN 1 ELSE 0 END) AS money_plus_goods,SUM(CASE WHEN r.amount=0 AND COALESCE(g.goods_qty,0)>0 THEN 1 ELSE 0 END) AS goods_only FROM returns r JOIN orders o ON o.id=r.order_id LEFT JOIN goods g ON g.return_id=r.id WHERE r.return_date>='2026-10-01' AND r.return_date<'2026-11-01' AND COALESCE(r.status,'completed')<>'cancelled' AND NOT EXISTS(SELECT 1 FROM exchanges e WHERE e.refund_return_id=r.id AND COALESCE(e.status,'completed')<>'cancelled') GROUP BY o.shipping_status ORDER BY o.shipping_status"},{"name":"PROD_SHORTAGE_TOTALS","sql":"WITH reserve AS (SELECT inventory_source,variant_id,SUM(quantity) AS reserved_qty FROM inventory_reservations WHERE status='active' AND variant_id IS NOT NULL AND inventory_source IN ('warehouse','boutique') GROUP BY inventory_source,variant_id), deficit AS (SELECT r.inventory_source,r.variant_id,r.reserved_qty,COALESCE(s.quantity,0) AS physical_qty FROM reserve r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.reserved_qty>COALESCE(s.quantity,0)) SELECT COUNT(*) AS shortage_sku_groups,COALESCE(SUM(reserved_qty-physical_qty),0) AS shortage_units FROM deficit"},{"name":"PROD_SHORTAGE_LIST","sql":"WITH reserve AS (SELECT inventory_source,variant_id,SUM(quantity) AS reserved_qty FROM inventory_reservations WHERE status='active' AND variant_id IS NOT NULL AND inventory_source IN ('warehouse','boutique') GROUP BY inventory_source,variant_id) SELECT r.inventory_source,r.variant_id,r.reserved_qty,COALESCE(s.quantity,0) AS physical_qty,r.reserved_qty-COALESCE(s.quantity,0) AS shortage_units FROM reserve r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.reserved_qty>COALESCE(s.quantity,0) ORDER BY shortage_units DESC,r.variant_id LIMIT 60"},{"name":"PROD_1563_CASE","sql":"SELECT o.id AS order_id,o.external_id,o.shipping_status,ret.id AS return_id,ret.return_date,ri.order_item_id,oi.product_name_snapshot,oi.stock_writeoff_status,ri.quantity AS returned_qty,ri.physical_received_at,ri.inventory_source,ir.status AS reservation_status,ir.variant_id,ir.quantity AS reservation_qty FROM returns ret JOIN orders o ON o.id=ret.order_id LEFT JOIN return_items ri ON ri.return_id=ret.id LEFT JOIN order_items oi ON oi.id=ri.order_item_id LEFT JOIN inventory_reservations ir ON ir.order_item_id=ri.order_item_id WHERE o.id=1563 ORDER BY ret.id,ri.id LIMIT 40"}]
for (const {name,sql} of queries){
 assert(/^\s*(?:SELECT|WITH)\b/i.test(sql) && !sql.includes(';') && !/\b(?:INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|REPLACE|PRAGMA|ATTACH|VACUUM|MERGE)\b/i.test(sql),'Only SELECT allowed')
 const r=await fetch(base+'/query',{method:'POST',headers,body:JSON.stringify({sql}),signal:AbortSignal.timeout(30000)})
 const data=await r.json()
 if(!r.ok||!data.success)throw Error(name+' failed: '+JSON.stringify({status:r.status,codes:(data.errors||[]).map(x=>x.code)}))
 console.log(name+' '+JSON.stringify(data.result?.[0]?.results||[]))
}
console.log('PROD_READ_ONLY_AUDIT_COMPLETE; zero writes; no D1 changes')
